import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The rows wiping in from the center outward and the accent band growing
// across the middle row. The rows' cruise runs for as long as the scene does
// and is not an element. Frames on the 30 fps scene timeline, after `speed`.
// The ids are public: a saved `timing` prop refers to them.

type TypeWallElementId = "rows" | "band";

/** The scene's timing does not depend on its props. */
type TypeWallTimingProps = object;

/** A row wipes in over `ENTRANCE`, `STAGGER` later for each row from the center. */
const ENTRANCE = 20;
const STAGGER = 2;
/** The accent band grows over these frames. */
const BAND = [6, 20] as const;

// `rows` is the center row's entrance; the row `k` away from the center
// starts `k` times its `stagger` beat later. How many rows there are depends
// on the frame height, not on the schedule.
const typeWallTimeline = defineTimeline<
  TypeWallElementId,
  TypeWallTimingProps
>((): TimelineElement<TypeWallElementId>[] => [
  {
    id: "rows",
    lane: "Rows",
    label: "rows",
    start: 0,
    length: ENTRANCE,
    beats: { stagger: STAGGER },
  },
  {
    id: "band",
    lane: "Band",
    label: "band",
    start: BAND[0],
    length: BAND[1] - BAND[0],
  },
]);

const { fontFamily: INTER } = loadInter("normal", {
  weights: ["900"],
  subsets: ["latin"],
});
const { fontFamily: ANTON } = loadAnton("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

type TypeWallStyle = "solid" | "narrow" | "outline";

interface TypeWallProps {
  text?: string;
  separator?: string;
  fontSize?: number;
  color?: string;
  accent?: string;
  accentText?: string;
  seed?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches the rows' entrance and the band, by the ids in
   * `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<TypeWallElementId>;
}

const typeWallDefaults = {
  text: "MOTION",
  separator: "·",
  fontSize: 64,
  color: "#fafafa",
  accent: "#D97757",
  accentText: "#0a0a0a",
  seed: 7,
  speed: 1,
} satisfies Required<Omit<TypeWallProps, "className" | "timing">>;

/** Row faces away from the center, the accent row always solid. */
const typeWallStyles: readonly TypeWallStyle[] = [
  "solid",
  "narrow",
  "outline",
];

/** Anton sized so its capitals match Inter's cap height (0.7275 / 0.8594 em). */
const NARROW_SCALE = 0.7275 / 0.8594;
/** Tokens per second at speed 1, before each row's seeded factor. */
const TOKENS_PER_SECOND = 0.22;
/** Tokens a row streams past on its way in, on top of its cruise. */
const ENTRANCE_BURST = 2.5;
/** Lower bound on a token's width per character, in em, for the repeat count. */
const MIN_CHAR_WIDTH = 0.4;
const MAX_TOKENS = 48;

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const easeOutCubic = Easing.out(Easing.cubic);

function finite(value: number | undefined, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function fract(x: number) {
  return x - Math.floor(x);
}

/** Maps a composition frame onto the 30 fps timeline, scaled by `speed`. */
function getTypeWallTime(
  frame: number,
  options: { fps?: number; speed?: number } = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const speed = Math.max(0, finite(options.speed, 1));
  return (Math.max(0, finite(frame, 0)) * 30 * speed) / fps;
}

/** Row indices from the top of the frame to the bottom; row 0 is centered. */
function getTypeWallRows(height: number, rowHeight: number) {
  const reach = Math.ceil((height / 2 - rowHeight / 2) / rowHeight) + 1;
  const rows: number[] = [];
  for (let k = -reach; k <= reach; k++) rows.push(k);
  return rows;
}

function getTypeWallStyle(row: number): TypeWallStyle {
  if (row === 0) return "solid";
  const n = typeWallStyles.length;
  return typeWallStyles[((row % n) + n) % n];
}

/** −1 runs left, 1 runs right. The accent row runs left. */
function getTypeWallDirection(row: number) {
  return Math.abs(row) % 2 === 0 ? -1 : 1;
}

/** Cruise speed in tokens per frame and the row's starting phase. */
function getTypeWallMotion(row: number, seed: number) {
  const factor = 0.7 + 0.6 * random(`type-wall-${seed}-speed-${row}`);
  return {
    velocity: (TOKENS_PER_SECOND * factor) / 30,
    phase: random(`type-wall-${seed}-phase-${row}`),
  };
}

interface TypeWallRowState {
  direction: number;
  /** Translation of the token strip in tokens, always in [−1, 0). */
  shift: number;
  /** Share of the row revealed from its entering side, 0..1. */
  reveal: number;
}

/** When the center row starts entering, over how long, and the step per row. */
interface TypeWallEntrance {
  start: number;
  length: number;
  stagger: number;
}

const DEFAULT_ENTRANCE: TypeWallEntrance = {
  start: 0,
  length: ENTRANCE,
  stagger: STAGGER,
};

function getTypeWallRow(
  t: number,
  row: number,
  seed = typeWallDefaults.seed,
  entrance: TypeWallEntrance = DEFAULT_ENTRANCE,
): TypeWallRowState {
  const direction = getTypeWallDirection(row);
  const { velocity, phase } = getTypeWallMotion(row, seed);
  const e = easeOutCubic(
    Math.min(
      1,
      Math.max(
        0,
        (t - (entrance.start + entrance.stagger * Math.abs(row))) /
          entrance.length,
      ),
    ),
  );
  const travel = phase + velocity * t + ENTRANCE_BURST * e;
  // Leftward rows slide the strip left; rightward rows run it from −1 up to 0.
  const shift = direction < 0 ? -fract(travel) : fract(travel) - 1;
  return { direction, shift: shift || 0, reveal: e };
}

/** The accent band growing from the center over `span`, 0..1. */
function getTypeWallBand(
  t: number,
  span: readonly [number, number] = BAND,
) {
  return interpolate(t, [...span], [0, 1], { ...CLAMP, easing: easeOutCubic });
}

/** Frame where the slowest (outermost) row has finished entering. */
function getTypeWallEntranceEnd(height: number, rowHeight: number) {
  const rows = getTypeWallRows(height, rowHeight);
  return ENTRANCE + STAGGER * Math.max(...rows.map(Math.abs));
}

/** How many tokens a strip needs to cover the width twice over. */
function getTypeWallTokenCount(
  width: number,
  fontSize: number,
  token: string,
) {
  const tokenWidth =
    Math.max(1, Array.from(token).length) * MIN_CHAR_WIDTH * fontSize;
  return Math.min(MAX_TOKENS, Math.ceil(width / tokenWidth) + 2);
}

function TypeWallBase(props: TypeWallProps) {
  const {
    text = typeWallDefaults.text,
    separator = typeWallDefaults.separator,
    fontSize = typeWallDefaults.fontSize,
    color = typeWallDefaults.color,
    accent = typeWallDefaults.accent,
    accentText = typeWallDefaults.accentText,
    seed = typeWallDefaults.seed,
    speed = typeWallDefaults.speed,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { fps, width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    typeWallTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const rowsEl = tl.get("rows");
  const bandEl = tl.get("band");
  const entrance = {
    start: rowsEl.start,
    length: rowsEl.length,
    stagger: rowsEl.beat("stagger"),
  };
  const unit = height / 720;
  const rowHeight = Math.max(8, fontSize * unit);
  const t = getTypeWallTime(frame, { fps, speed });
  const rows = getTypeWallRows(height, rowHeight);
  const token = `${text} ${separator} `;
  const band = getTypeWallBand(t, [bandEl.start, bandEl.end]);
  const outlineId = `type-wall-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      {/* Outline from the filled silhouette: the variable font's overlapping
          contours would show through a text stroke. */}
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <defs>
          <filter id={outlineId}>
            <feMorphology
              in="SourceAlpha"
              operator="erode"
              radius={1.5 * unit}
              result="inner"
            />
            <feComposite
              in="SourceAlpha"
              in2="inner"
              operator="out"
              result="ring"
            />
            <feFlood floodColor={color} />
            <feComposite in2="ring" operator="in" />
          </filter>
        </defs>
      </svg>
      {rows.map((row) => {
        const style = getTypeWallStyle(row);
        const state = getTypeWallRow(t, row, seed, entrance);
        const narrow = style === "narrow";
        const size = narrow ? rowHeight * NARROW_SCALE : rowHeight;
        const count = getTypeWallTokenCount(width, size, token);
        const onBand = row === 0;
        const hidden = `${(1 - state.reveal) * 100}%`;
        return (
          <div
            key={row}
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: height / 2 + (row - 0.5) * rowHeight,
              height: rowHeight,
              clipPath:
                state.direction < 0
                  ? `inset(0 0 0 ${hidden})`
                  : `inset(0 ${hidden} 0 0)`,
            }}
          >
            {onBand ? (
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: accent,
                  transform: `scaleX(${band})`,
                }}
              />
            ) : null}
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                width: "max-content",
                height: "100%",
                display: "flex",
                alignItems: "center",
                whiteSpace: "pre",
                fontFamily: narrow ? ANTON : INTER,
                fontSize: size,
                lineHeight: 1,
                fontWeight: narrow ? 400 : 900,
                color: onBand ? accentText : color,
                filter: style === "outline" ? `url(#${outlineId})` : undefined,
                transform: `translateX(${(state.shift * 100) / count}%)`,
              }}
            >
              {Array.from({ length: count }, (_, i) => (
                <span key={i}>{token}</span>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "MOTION",
    description: "Text",
  },
  separator: {
    type: "text-content",
    default: "·",
    description: "Separator",
  },
  color: {
    type: "color",
    default: "#fafafa",
    description: "Text color",
  },
  accent: {
    type: "color",
    default: "#ff4d1a",
    description: "Band color",
  },
  accentText: {
    type: "color",
    default: "#111111",
    description: "Band text",
  },
  fontSize: {
    type: "number",
    default: 64,
    min: 24,
    max: 180,
    step: 2,
    description: "Row height",
    hiddenFromList: false,
  },
  seed: {
    type: "number",
    default: 7,
    min: 0,
    max: 99,
    step: 1,
    description: "Seed",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","separator","color","accent","accentText","fontSize","seed","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "MOTION",
  separator: "·",
  color: "#fafafa",
  accent: "#ff4d1a",
  accentText: "#111111",
  fontSize: 64,
  seed: 7,
  speed: 1,
};

type TypeWallElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TypeWallBase>;

const TypeWallInner = forwardRef<
  HTMLDivElement,
  TypeWallElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TypeWall>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TypeWallBase
          {...(componentProps as unknown as ComponentProps<typeof TypeWallBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TypeWall = Interactive.withSchema({
  Component: TypeWallInner,
  componentName: "<TypeWall>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
